import pandas as pd


def _is_null(x):
    try:
        return pd.isna(x)
    except (TypeError, ValueError):
        return x is None


def _attrs_equal(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def _get_input(inputs, name):
    if name in inputs:
        return inputs[name]
    # Try case-insensitive match
    lower_map = {k.lower(): k for k in inputs.keys()}
    key = lower_map.get(name.lower())
    if key is not None:
        return inputs[key]
    raise KeyError(name)


def run(inputs: dict) -> dict:
    dim_store = _get_input(inputs, "DIM_STORE").copy()
    stg_store_full = _get_input(inputs, "STG_STORE_FULL")
    batch_control = _get_input(inputs, "BATCH_CONTROL")

    # Exactly one row expected in BATCH_CONTROL
    b = batch_control["batch_date"].iloc[0]

    # Distinct snapshot rows (exact duplicates collapse)
    S = stg_store_full[["store_id", "region", "format"]].drop_duplicates()

    # Current rows in dim_store
    current_mask = dim_store["is_current"] == 1
    current = dim_store[current_mask]

    # Build a lookup from store_id -> first current row (should be unique per store_id)
    current_by_id = {}
    for idx, row in current.iterrows():
        sid = row["store_id"]
        if sid not in current_by_id:
            current_by_id[sid] = (idx, row)

    rows_to_close_idx = []
    rows_to_insert = []

    S_ids = set()

    for _, s in S.iterrows():
        sid = s["store_id"]
        S_ids.add(sid)

        if sid in current_by_id:
            c_idx, c_row = current_by_id[sid]
            region_differs = not _attrs_equal(c_row["region"], s["region"])
            format_differs = not _attrs_equal(c_row["format"], s["format"])

            if region_differs or format_differs:
                rows_to_close_idx.append(c_idx)
                rows_to_insert.append(
                    {
                        "store_id": sid,
                        "region": s["region"],
                        "format": s["format"],
                        "eff_start_date": b,
                        "eff_end_date": pd.NaT,
                        "is_current": 1,
                    }
                )
            # else: no-op, unchanged attributes
        else:
            # brand-new store OR reopened store: always gets a new version
            rows_to_insert.append(
                {
                    "store_id": sid,
                    "region": s["region"],
                    "format": s["format"],
                    "eff_start_date": b,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
            )

    # Close current rows for store_ids not present in S (closed stores)
    for sid, (c_idx, c_row) in current_by_id.items():
        if sid not in S_ids:
            rows_to_close_idx.append(c_idx)

    # Apply closes to dim_store
    if rows_to_close_idx:
        dim_store.loc[rows_to_close_idx, "eff_end_date"] = b
        dim_store.loc[rows_to_close_idx, "is_current"] = 0

    # Append new inserted rows
    if rows_to_insert:
        insert_df = pd.DataFrame(
            rows_to_insert,
            columns=[
                "store_id",
                "region",
                "format",
                "eff_start_date",
                "eff_end_date",
                "is_current",
            ],
        )
        dim_store_out = pd.concat([dim_store, insert_df], ignore_index=True)
    else:
        dim_store_out = dim_store

    dim_store_out = dim_store_out[
        ["store_id", "region", "format", "eff_start_date", "eff_end_date", "is_current"]
    ].reset_index(drop=True)

    return {"dim_store_out": dim_store_out}
